    prim_cfg: Dict[str, Dict[str, Any]] = combo_cfg.get("primitives", {})
    primitives: Dict[str, Any] = {}
    for key, spec in prim_cfg.items():
        cls = primitive_classes.get(spec.get("class"))
        if cls is None:
            continue
        params = spec.get("params", {})
        try:
            primitives[key] = cls(**params)
        except Exception:
            primitives[key] = cls()  # safe default

    # normalize canonical primitive keys
    if "p10" not in primitives and "P10" in primitives:
        primitives["p10"] = primitives.pop("P10")
    if "p12" not in primitives and "P12" in primitives:
